package pe.edu.upeu.notificacion.entity; import jakarta.persistence.*; import lombok.*; import java.time.*; @Entity @Table(name="notificaciones") @Getter @Setter @NoArgsConstructor public class Notificacion{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="usuario_id",nullable=false)private Long usuarioId;@Column(nullable=false,length=60)private String tipo;@Enumerated(EnumType.STRING)@Column(nullable=false,length=15)private Canal canal;@Column(nullable=false,length=180)private String asunto;@Column(nullable=false,length=1200)private String mensaje;@Enumerated(EnumType.STRING)@Column(nullable=false,length=15)private Estado estado;@Column(nullable=false)private boolean leida;@Column(name="fecha_creacion",nullable=false)private LocalDateTime fechaCreacion;@Column(name="fecha_envio")private LocalDateTime fechaEnvio;@Column(name="detalle_envio",length=300)private String detalleEnvio;public enum Canal{IN_APP,EMAIL}public enum Estado{PENDIENTE,ENVIADA,SIMULADA,FALLIDA}}